{
  "title": "k-平移距离的定义可视化",
  "preferred_geogebra_app": "geometry",
  "execution_mode": "command_only",
  "math_meaning_summary": "该可视化逐步构建了'k-平移距离'的几何定义。它展示了对于给定的点A, B和一个圆，如何找到两条与线段AB平行且等长的弦，并由此确定两个可能的平移向量。'k'值最终被确定为这两个平移距离中较大的一个。",
  "object_naming_convention": "遵循数学惯例，初始点为A和B，圆心为O，平移后的点为A'_1, A'_2。",
  "commands": [
    {
      "step": 1,
      "purpose": "创建交互式步骤控制器。",
      "command": "step = Slider(0, 4, 1)"
    },
    {
      "step": 2,
      "purpose": "创建初始几何对象：圆和点。",
      "command": "O = (0,0)"
    },
    {
      "step": 3,
      "purpose": "创建初始几何对象：圆和点。",
      "command": "c = Circle(O, 1)"
    },
    {
      "step": 4,
      "purpose": "创建初始几何对象：圆和点。",
      "command": "A = (-1, sqrt(3))"
    },
    {
      "step": 5,
      "purpose": "创建初始几何对象：圆和点。",
      "command": "B = (-1/2, sqrt(3)/2)"
    },
    {
      "step": 6,
      "purpose": "创建初始线段。",
      "command": "s_AB = Segment(A, B)"
    },
    {
      "step": 7,
      "purpose": "计算构建所需的核心几何参数。",
      "command": "M_AB = Midpoint(A, B)"
    },
    {
      "step": 8,
      "purpose": "计算构建所需的核心几何参数。",
      "command": "dist_OM = sqrt(1 - Distance(A, M_AB)^2)"
    },
    {
      "step": 9,
      "purpose": "计算构建所需的核心几何参数。",
      "command": "dir_perp = PerpendicularVector(Vector(B - A))"
    },
    {
      "step": 10,
      "purpose": "计算两个可能的弦的中点。",
      "command": "M1 = O + dist_OM * UnitVector(dir_perp)"
    },
    {
      "step": 11,
      "purpose": "计算两个可能的弦的中点。",
      "command": "M2 = O - dist_OM * UnitVector(dir_perp)"
    },
    {
      "step": 12,
      "purpose": "定义两个平移向量。",
      "command": "v_trans1 = Vector(M_AB, M1)"
    },
    {
      "step": 13,
      "purpose": "定义两个平移向量。",
      "command": "v_trans2 = Vector(M_AB, M2)"
    },
    {
      "step": 14,
      "purpose": "定义平移后弦的端点，这些是后续步骤的基础。",
      "command": "A_1p_base = A + v_trans1"
    },
    {
      "step": 15,
      "purpose": "定义平移后弦的端点。",
      "command": "B_1p_base = B + v_trans1"
    },
    {
      "step": 16,
      "purpose": "定义平移后弦的端点。",
      "command": "A_2p_base = A + v_trans2"
    },
    {
      "step": 17,
      "purpose": "定义平移后弦的端点。",
      "command": "B_2p_base = B + v_trans2"
    },
    {
      "step": 18,
      "purpose": "根据步骤创建第一条可能的弦。",
      "command": "chord1 = If(step >= 1, Segment(A_1p_base, B_1p_base))"
    },
    {
      "step": 19,
      "purpose": "根据步骤创建第二条可能的弦。",
      "command": "chord2 = If(step >= 1, Segment(A_2p_base, B_2p_base))"
    },
    {
      "step": 20,
      "purpose": "根据步骤显示点A的第一个平移目标点。",
      "command": "A_1p = If(step >= 2, A_1p_base)"
    },
    {
      "step": 21,
      "purpose": "根据步骤显示点A的第二个平移目标点。",
      "command": "A_2p = If(step >= 2, A_2p_base)"
    },
    {
      "step": 22,
      "purpose": "根据步骤绘制第一个平移向量的可视化线段。",
      "command": "trans_seg1 = If(step >= 3, Segment(A, A_1p_base))"
    },
    {
      "step": 23,
      "purpose": "根据步骤绘制第二个平移向量的可视化线段。",
      "command": "trans_seg2 = If(step >= 3, Segment(A, A_2p_base))"
    },
    {
      "step": 24,
      "purpose": "计算两个平移距离。",
      "command": "d1 = Length(v_trans1)"
    },
    {
      "step": 25,
      "purpose": "计算两个平移距离。",
      "command": "d2 = Length(v_trans2)"
    },
    {
