{
  "title": "探索“最远平移距离”k",
  "preferred_geogebra_app": "geometry",
  "execution_mode": "command_only",
  "math_meaning_summary": "该可视化旨在解释“最远平移距离 k”的定义。通过拖动滑块，用户可以观察线段 PQ 在平移成为圆的弦 P'Q' 时的所有可能情况。图中动态显示了平移距离 |PP'| 和其理论最大值 k，帮助学生直观理解 k 是当平移向量与 M、T、M' 共线时取得的。",
  "object_naming_convention": "点使用大写字母（如P, Q, T, M），圆和线段使用描述性小写名称（如circT, segPQ）。撇号（'）用于表示平移后的对应点（如M'）。",
  "commands": [
    {
      "step": 1,
      "purpose": "定义目标圆的圆心",
      "command": "T = (3, 2)"
    },
    {
      "step": 2,
      "purpose": "定义目标圆",
      "command": "circT = Circle(T, 3)"
    },
    {
      "step": 3,
      "purpose": "定义初始线段的起点（可拖动）",
      "command": "P = (-3, 4)"
    },
    {
      "step": 4,
      "purpose": "定义初始线段的终点（可拖动）",
      "command": "Q = (-4, 2)"
    },
    {
      "step": 5,
      "purpose": "创建初始线段",
      "command": "segPQ = Segment(P, Q)"
    },
    {
      "step": 6,
      "purpose": "计算初始线段的中点",
      "command": "M = Midpoint(P, Q)"
    },
    {
      "step": 7,
      "purpose": "计算平移后线段中点M'的轨迹圆半径。如果PQ长度大于圆直径，d将是未定义的。",
      "command": "d = sqrt(3^2 - (Distance(P, Q) / 2)^2)"
    },
    {
      "step": 8,
      "purpose": "创建M'的轨迹圆",
      "command": "circM = Circle(T, d)"
    },
    {
      "step": 9,
      "purpose": "创建滑块以控制M'在轨迹圆上的位置",
      "command": "alpha = Slider(0, 2*pi)"
    },
    {
      "step": 10,
      "purpose": "根据滑块alpha定义M'的位置",
      "command": "M_prime = Point(circM, alpha / (2*pi))"
    },
    {
      "step": 11,
      "purpose": "根据平移向量MM'计算P点平移后的位置P'",
      "command": "P_prime = Translate(P, Vector(M, M_prime))"
    },
    {
      "step": 12,
      "purpose": "根据平移向量MM'计算Q点平移后的位置Q'",
      "command": "Q_prime = Translate(Q, Vector(M, M_prime))"
    },
    {
      "step": 13,
      "purpose": "创建平移后的弦P'Q'",
      "command": "chordPprimeQprime = Segment(P_prime, Q_prime)"
    },
    {
      "step": 14,
      "purpose": "创建表示平移距离的线段PP'",
      "command": "segPPprime = Segment(P, P_prime)"
    },
    {
      "step": 15,
      "purpose": "创建动态文本显示当前平移距离",
      "command": "dist_text = Text(\"平移距离 |PP'| = \" + segPPprime)"
    },
    {
      "step": 16,
      "purpose": "创建动态文本显示最远平移距离k的理论值",
      "command": "k_text = Text(\"最远平移距离 k = \" + (Distance(T, M) + d))"
    }
