      "step": 2,
      "purpose": "创建原点O",
      "command": "O = (0,0)"
    },
    {
      "step": 3,
      "purpose": "创建定点A",
      "command": "A = (-1, sqrt(3))"
    },
    {
      "step": 4,
      "purpose": "创建点C运动的轨迹圆circA",
      "command": "circA = Circle(A, 1)"
    },
    {
      "step": 5,
      "purpose": "根据滑块beta在圆circA上创建动点C",
      "command": "C = A + (cos(beta), sin(beta))"
    },
    {
      "step": 6,
      "purpose": "创建AC的中点M",
      "command": "M = Midpoint(A, C)"
    },
    {
      "step": 7,
      "purpose": "创建线段OM",
      "command": "s_OM = Segment(O, M)"
