{
  "title": "解构“k-最远平移距离”",
  "preferred_geogebra_app": "geometry",
  "execution_mode": "command_only",
  "math_meaning_summary": "该可视化展示了如何通过几何作图来确定“k-最远平移距离”。关键步骤是构造两个辅助圆，其交点决定了所有可能的平移。k的值就是圆心T到这些交点的最大距离。",
  "object_naming_convention": "使用简短的英文标签，如P, Q, T, C1, C2, r。对于解题中的点，使用其原始名称，如A, B₄, O。",
  "commands": [
    {
      "step": 1,
      "purpose": "定义圆心、线段端点和半径。",
      "command": "T=(0,0)"
    },
    {
      "step": 1,
      "purpose": "定义圆心、线段端点和半径。",
      "command": "P=(-1, sqrt(3))"
    },
    {
      "step": 1,
      "purpose": "定义圆心、线段端点和半径。",
      "command": "Q=(-1/2, sqrt(3)/2)"
    },
    {
      "step": 1,
      "purpose": "定义圆心、线段端点和半径。",
      "command": "r=1"
    },
    {
      "step": 2,
      "purpose": "绘制目标圆。",
      "command": "circ_T=Circle(T, r)"
    },
    {
      "step": 3,
      "purpose": "根据几何约束，构造第一个辅助圆。",
      "command": "circ_P_aux=Circle(P, r)"
    },
    {
      "step": 4,
      "purpose": "根据几何约束，构造第二个辅助圆。",
      "command": "circ_Q_aux=Circle(Q, r)"
    },
    {
      "step": 5,
      "purpose": "找到两个辅助圆的交点C1。",
      "command": "C1 = Intersect(circ_P_aux, circ_Q_aux, 1)"
    },
    {
      "step": 5,
      "purpose": "找到两个辅助圆的交点C2。",
      "command": "C2 = Intersect(circ_P_aux, circ_Q_aux, 2)"
    },
    {
      "step": 6,
      "purpose": "显示从圆心到交点C1的距离线段。",
      "command": "d1=Segment(T, C1)"
    },
    {
      "step": 6,
      "purpose": "显示从圆心到交点C2的距离线段。",
      "command": "d2=Segment(T, C2)"
    },
    {
      "step": 7,
      "purpose": "计算k值，即两个距离中的最大值。",
      "command": "k = Max(Distance(T, C1), Distance(T, C2))"
    },
    {
      "step": 7,
      "purpose": "显示计算出的k值。",
      "command": "k_text = Text(\"k = \" + Round(k, 2), (-3.5, 3.5))"
    },
    {
      "step": 8,
      "purpose": "确定产生最大距离的交点。",
      "command": "C_max = If(Distance(T, C1) >= Distance(T, C2), C1, C2)"
    },
    {
      "step": 9,
      "purpose": "定义实现最大距离平移的向量。",
      "command": "v = Vector(C_max, T)"
    },
    {
      "step": 10,
      "purpose": "绘制与k值对应的最终平移弦。",
      "command": "chord_1 = Segment(Translate(P, v), Translate(Q, v))"
    }
