{
  "title": "“k-平移点” 定义的可视化",
  "preferred_geogebra_app": "geometry",
  "execution_mode": "command_only",
  "math_meaning_summary": "该可视化展示了如何根据给定的线段 PQ 和圆 ⊙T 构造“k-最远平移距离”。它通过平移圆心找到可能的目标点 P'，这些点是原始圆和平移后圆的交点。k 值是点 P 到这些交点的最大距离。",
  "object_naming_convention": "点 T（圆心）命名为 O，点 P 命名为 A，点 Q 命名为 B₄。平移后的圆命名为 c_shifted，交点命名为 P'_1 和 P'_2。",
  "commands": [
    {
      "step": 1,
      "purpose": "创建圆心 O",
      "command": "T = (0,0)"
    },
    {
      "step": 2,
      "purpose": "创建点 A",
      "command": "P = (-1, sqrt(3))"
    },
    {
      "step": 3,
      "purpose": "创建点 B₄",
      "command": "Q = (-1/2, sqrt(3)/2)"
    },
    {
      "step": 4,
      "purpose": "创建单位圆 ⊙O",
      "command": "c_T = Circle(T, 1)"
    },
    {
      "step": 5,
      "purpose": "创建初始线段 AB₄",
      "command": "segPQ = Segment(P, Q)"
    },
    {
      "step": 6,
      "purpose": "创建平移向量 v = B₄ - A",
      "command": "v_PQ = Vector(P, Q)"
    },
    {
      "step": 7,
      "purpose": "创建平移后的圆心 T'",
      "command": "T_shifted = T - v_PQ"
    },
    {
      "step": 8,
      "purpose": "创建平移后的圆 c_shifted",
      "command": "c_shifted = Circle(T_shifted, 1)"
    },
    {
      "step": 9,
      "purpose": "找到两个圆的交点列表",
      "command": "IntersectPoints = Intersect(c_T, c_shifted)"
    },
    {
      "step": 10,
      "purpose": "定义第一个交点 P'_1",
      "command": "P_prime_1 = Element(IntersectPoints, 1)"
    },
    {
      "step": 11,
      "purpose": "定义第二个交点 P'_2",
      "command": "P_prime_2 = Element(IntersectPoints, 2)"
    },
    {
      "step": 12,
      "purpose": "创建从 A 到 P'_1 的距离线段",
      "command": "seg_dist1 = Segment(P, P_prime_1)"
    },
    {
      "step": 13,
      "purpose": "创建从 A 到 P'_2 的距离线段",
      "command": "seg_dist2 = Segment(P, P_prime_2)"
    },
    {
      "step": 14,
      "purpose": "计算 k 值",
      "command": "k = Max(Distance(P, P_prime_1), Distance(P, P_prime_2))"
    },
    {
      "step": 15,
      "purpose": "显示 k 值",
      "command": "k_text = Text(\"k = \" + k, (-2.5, 2.5))"
    }
  ],
  "property_commands": [
