      "command": "Q = (0, 1)"
    },
    {
      "step": 3,
      "purpose": "创建圆心 T",
      "command": "T = (0, 4)"
    },
    {
      "step": 4,
      "purpose": "创建半径 r 的滑块",
      "command": "r = Slider(0.5, 5, 0.1, 2.5)"
    },
    {
      "step": 5,
      "purpose": "创建控制构建步骤的滑块",
      "command": "step = Slider(0, 5, 1, 0)"
    },
    {
      "step": 6,
      "purpose": "创建目标圆 cT",
      "command": "cT = Circle(T, r)"
    },
    {
      "step": 7,
      "purpose": "创建初始线段 sPQ",
      "command": "sPQ = Segment(P, Q)"
    },
    {
      "step": 8,
      "purpose": "找到线段 PQ 的中点 M",
      "command": "M = Midpoint(sPQ)"
    },
    {
      "step": 9,
      "purpose": "计算中点轨迹圆的半径 r_M",
